const appById=id=>db.prepare('SELECT * FROM staff_apps WHERE id=?').get(id), rank=k=>RANKS.find(r=>r.key===k), has=(m,id)=>!!id&&m?.roles?.cache?.has(id), leadership=m=>has(m,OWNER)||has(m,COOWNER), seniorPlus=m=>leadership(m)||has(m,HEAD_SENIOR)||has(m,SENIOR);
