async function text(id){const c=await client.channels.fetch(id).catch(()=>null);return c?.isTextBased()?c:null;}
function currentRank(m){for(const r of [...RANKS].reverse())if(has(m,r.role))return r.key;return has(m,SMP)?'member':null;}
function normalTargets(m){const c=currentRank(m);if(c==='member')return['general'];if(c==='general')return['head_general','senior'];if(c==='head_general')return['senior'];if(c==='senior')return['head_senior'];if(c==='head_senior')return['co_owner'];if(c==='co_owner')return['owner'];return[];}
function panel(){return new EmbedBuilder().setTitle('🛡️ KIND SMP Staff Applications').setDescription(`**Public applications:** ${setting('open')==='1'?'🟢 Open':'🔴 Closed'}\n\nUse **Direct Interview** for a leadership-selected member. Senior Staff+ should set availability so KIND BOSS can offer interview times automatically.`);}
function panelRows(){return [new ActionRowBuilder().addComponents(new ButtonBuilder().setCustomId('sa:open').setLabel('Open Applications').setStyle(ButtonStyle.Success),new ButtonBuilder().setCustomId('sa:close').setLabel('Close Applications').setStyle(ButtonStyle.Danger),new ButtonBuilder().setCustomId('sa:direct').setLabel('Direct Interview').setStyle(ButtonStyle.Primary)),new ActionRowBuilder().addComponents(new ButtonBuilder().setCustomId('sa:availability').setLabel('🗓️ Set Availability').setStyle(ButtonStyle.Secondary),new ButtonBuilder().setCustomId('sa:myAvailability').setLabel('📅 My Availability').setStyle(ButtonStyle.Secondary),new ButtonBuilder().setCustomId('sa:availabilityHelp').setLabel('❓ Availability Help').setStyle(ButtonStyle.Secondary))];}
async function ensureControl(){const c=await text(CONTROL);if(!c)return;const ms=await c.messages.fetch({limit:100}).catch(()=>null);const ps=ms?[...ms.values()].filter(m=>m.author?.id===client.user.id&&m.components?.some(r=>r.components?.some(x=>x.customId==='sa:open'))):[];ps.sort((a,b)=>b.createdTimestamp-a.createdTimestamp);for(const d of ps.slice(1))await d.delete().catch(()=>{});return ps[0]?ps[0].edit({embeds:[panel()],components:panelRows()}):c.send({embeds:[panel()],components:panelRows()});}
async function deletePublic(){const id=setting('public_channel');if(id){const c=await client.channels.fetch(id).catch(()=>null);if(c)await c.delete('Staff applications closed').catch(()=>{});}setSetting('public_channel','');}
async function openPublic(g){let c=setting('public_channel')?await g.channels.fetch(setting('public_channel')).catch(()=>null):null;if(!c)c=await g.channels.create({name:'📋・staff-applications',type:ChannelType.GuildText,parent:COMMUNITY,permissionOverwrites:[{id:g.roles.everyone.id,deny:[PermissionFlagsBits.ViewChannel]},{id:SMP,allow:[PermissionFlagsBits.ViewChannel,PermissionFlagsBits.ReadMessageHistory],deny:[PermissionFlagsBits.SendMessages]},{id:GENERAL,allow:[PermissionFlagsBits.ViewChannel,PermissionFlagsBits.ReadMessageHistory],deny:[PermissionFlagsBits.SendMessages]},{id:SENIOR,allow:[PermissionFlagsBits.ViewChannel,PermissionFlagsBits.ReadMessageHistory],deny:[PermissionFlagsBits.SendMessages]},{id:OWNER,allow:[PermissionFlagsBits.ViewChannel,PermissionFlagsBits.ReadMessageHistory]}]});setSetting('public_channel',c.id);await c.send({embeds:[new EmbedBuilder().setTitle('🛡️ Staff Applications Are Open').setDescription('SMP Members may apply for **General Staff**. Existing staff may apply for an eligible higher rank.\n\nA higher rank means more responsibility and trust.')],components:[new ActionRowBuilder().addComponents(new ButtonBuilder().setCustomId('sa:apply').setLabel('Apply for Staff / Promotion').setStyle(ButtonStyle.Success))]});return c;}
function targetMenu(id,keys,direct=false){return new ActionRowBuilder().addComponents(new StringSelectMenuBuilder().setCustomId(`sa:target:${id}:${direct?'direct':'normal'}`).setPlaceholder('Choose target rank').addOptions(keys.map(k=>({label:rank(k).label,value:k}))));}
function appModal(target,source,userId){return new ModalBuilder().setCustomId(`sa:submit:${target}:${source}:${userId}`).setTitle(`Apply: ${rank(target).label}`).addComponents(new ActionRowBuilder().addComponents(new TextInputBuilder().setCustomId('why').setLabel('Why do you want this rank?').setStyle(TextInputStyle.Paragraph).setRequired(true)),new ActionRowBuilder().addComponents(new TextInputBuilder().setCustomId('experience').setLabel('Staff/moderation experience').setStyle(TextInputStyle.Paragraph).setRequired(true)),new ActionRowBuilder().addComponents(new TextInputBuilder().setCustomId('judgment').setLabel('How would you handle a difficult conflict?').setStyle(TextInputStyle.Paragraph).setRequired(true)));}
async function createPrivateChannel(g,userId,target){const member=await g.members.fetch(userId);return g.channels.create({name:`application-${member.user.username}`.toLowerCase().replace(/[^a-z0-9-]/g,'-').slice(0,90),type:ChannelType.GuildText,parent:APP_CATEGORY,permissionOverwrites:[{id:g.roles.everyone.id,deny:[PermissionFlagsBits.ViewChannel]},{id:userId,allow:[PermissionFlagsBits.ViewChannel,PermissionFlagsBits.SendMessages,PermissionFlagsBits.ReadMessageHistory]},{id:SENIOR,allow:[PermissionFlagsBits.ViewChannel,PermissionFlagsBits.SendMessages,PermissionFlagsBits.ReadMessageHistory]},{id:HEAD_SENIOR,allow:[PermissionFlagsBits.ViewChannel,PermissionFlagsBits.SendMessages,PermissionFlagsBits.ReadMessageHistory]},{id:COOWNER,allow:[PermissionFlagsBits.ViewChannel,PermissionFlagsBits.SendMessages,PermissionFlagsBits.ReadMessageHistory]},{id:OWNER,allow:[PermissionFlagsBits.ViewChannel,PermissionFlagsBits.SendMessages,PermissionFlagsBits.ReadMessageHistory]}]});}
function studyGuideEmbed(a){const extras={general:'everyday moderation, evidence, fairness, escalation and calm communication',head_general:'training General Staff, resolving staff disagreements, report organization and escalation',senior:'serious cheating investigations, ban evasion, exploits, appeals and multi-person investigations',head_senior:'reviewing major punishments, Senior Staff disagreements, staff-abuse investigations, difficult appeals and escalation',co_owner:'leadership complaints, intervention, promotions/demotions, major exploits and leadership disagreements',owner:'final responsibility, avoiding micromanagement, infrastructure/security and correcting major decisions'};return new EmbedBuilder().setTitle(`📚 Study Guide — ${rank(a.target_rank).label}`).setDescription(`Prepare for these core areas:\n• Staff knowledge & chain of command\n• Partial-anarchy judgment\n• Evidence & investigations\n• Strikes, jail & punishments\n• Staff integrity\n• Leadership & escalation\n• Emergency judgment\n• Professionalism\n\n🎯 **Rank focus:** ${extras[a.target_rank]||'responsibilities of the target rank'}\n\n💡 Do not memorize scripted answers. Be ready to explain **why** you would make a decision. Exact interview questions are not shown.`);}
function availabilityHelp(){return new EmbedBuilder().setTitle('📅 How to Set Interview Availability').setDescription('**1.** Press **🗓️ Set Availability**.\n**2.** Select the days that share the same hours.\n**3.** Select **From** and **Until** using AM/PM.\n**4.** Select your timezone.\n**5.** Press **➕ Add Availability** to save that group.\n**6.** Change the days/times and press **➕ Add This Group** again for a different schedule.\n**7.** Repeat as many times as needed.\n**8.** Press **💾 Finish & Save All** when done.\n\nExample: Monday/Wednesday/Friday can be **4:00 PM - 8:00 PM**, while Saturday/Sunday can be **12:00 PM - 5:00 PM**. KIND BOSS combines every group when finding times where at least two eligible interviewers overlap.');}
const DAY={sun:7,mon:1,tue:2,wed:3,thu:4,fri:5,sat:6};
const DAY_NAMES=[['mon','Monday'],['tue','Tuesday'],['wed','Wednesday'],['thu','Thursday'],['fri','Friday'],['sat','Saturday'],['sun','Sunday']];
const TZ_OPTIONS=[['Pacific/Honolulu','Hawaii (HST)'],['America/Los_Angeles','Pacific Time'],['America/Denver','Mountain Time'],['America/Chicago','Central Time'],['America/New_York','Eastern Time'],['America/Anchorage','Alaska Time']];
const availabilityDrafts=new Map();
function hourLabel(h){const ap=h<12?'AM':'PM',hr=h%12||12;return `${hr}:00 ${ap}`;}
function blankGroup(){return {days:[],start:null,end:null};}
function getAvailDraft(userId){let d=availabilityDrafts.get(userId);if(!d){d={tz:null,groups:[],editing:blankGroup()};availabilityDrafts.set(userId,d);}return d;}
function groupSummary(g,n){const days=g.days?.length?g.days.map(x=>DAY_NAMES.find(y=>y[0]===x)?.[1]).join(', '):'No days';return `**Group ${n}:** ${days}\n${hourLabel(g.start)} - ${hourLabel(g.end)}`;}
function availabilitySummary(d){const groups=d.groups?.length?d.groups.map((g,n)=>groupSummary(g,n+1)).join('\n\n'):'*No availability groups saved yet.*';const tz=d.tz?TZ_OPTIONS.find(x=>x[0]===d.tz)?.[1]||d.tz:'Not selected';return `${groups}\n\n**Timezone:** ${tz}`;}
function availabilityRows(userId){const d=getAvailDraft(userId),g=d.editing||blankGroup();const dayMenu=new StringSelectMenuBuilder().setCustomId('sa:availDays').setPlaceholder(g.days.length?`${g.days.length} day(s) selected`:'Select days for this availability').setMinValues(1).setMaxValues(7).addOptions(DAY_NAMES.map(([v,l])=>({label:l,value:v,default:g.days.includes(v)})));const timeOpts=Array.from({length:24},(_,h)=>({label:hourLabel(h),value:String(h)}));const start=new StringSelectMenuBuilder().setCustomId('sa:availStart').setPlaceholder(g.start===null?'Available from...':`From ${hourLabel(g.start)}`).addOptions(timeOpts.map(o=>({...o,default:Number(o.value)===g.start})));const end=new StringSelectMenuBuilder().setCustomId('sa:availEnd').setPlaceholder(g.end===null?'Available until...':`Until ${hourLabel(g.end)}`).addOptions(timeOpts.map(o=>({...o,default:Number(o.value)===g.end})));const tz=new StringSelectMenuBuilder().setCustomId('sa:availTz').setPlaceholder(d.tz?TZ_OPTIONS.find(x=>x[0]===d.tz)?.[1]||d.tz:'Select your timezone').addOptions(TZ_OPTIONS.map(([v,l])=>({label:l,value:v,default:d.tz===v})));return [new ActionRowBuilder().addComponents(dayMenu),new ActionRowBuilder().addComponents(start),new ActionRowBuilder().addComponents(end),new ActionRowBuilder().addComponents(tz),new ActionRowBuilder().addComponents(new ButtonBuilder().setCustomId('sa:availAddGroup').setLabel(d.groups.length?'➕ Add This Group':'➕ Add Availability').setStyle(ButtonStyle.Primary),new ButtonBuilder().setCustomId('sa:availFinish').setLabel('💾 Finish & Save All').setStyle(ButtonStyle.Success),new ButtonBuilder().setCustomId('sa:availCancel').setLabel('Cancel').setStyle(ButtonStyle.Secondary))];}
function windowsFromGroups(d){return d.groups.flatMap(g=>g.days.map(day=>`${day[0].toUpperCase()+day.slice(1)} ${String(g.start).padStart(2,'0')}:00-${String(g.end).padStart(2,'0')}:00`)).join('\n');}
function displayWindows(tz,raw){const wins=parseWindows(tz,raw)||[];return wins.map(w=>{const day=DAY_NAMES.find(([k])=>DAY[k]===w.weekday)?.[1]||'Day';return `${day}: ${hourLabel(w.sh)} - ${hourLabel(w.eh)}`;}).join('\n');}
function parseWindows(tz,raw){if(!DateTime.now().setZone(tz).isValid)return null;const out=[];for(const line of raw.split(/\n+/).map(x=>x.trim()).filter(Boolean)){const m=line.match(/^(Sun|Mon|Tue|Wed|Thu|Fri|Sat)\s+(\d{1,2}):(\d{2})-(\d{1,2}):(\d{2})$/i);if(!m)return null;const vals=m.slice(2).map(Number);if(vals[0]>23||vals[1]>59||vals[2]>23||vals[3]>59)return null;out.push({weekday:DAY[m[1].toLowerCase()],sh:vals[0],sm:vals[1],eh:vals[2],em:vals[3]});}return out.length?out:null;}
function nextOccurrences(row,days=21){const wins=parseWindows(row.timezone,row.windows)||[], now=DateTime.now().setZone(row.timezone), out=[];for(let d=0;d<days;d++){const date=now.startOf('day').plus({days:d});for(const w of wins)if(date.weekday===w.weekday){const s=date.set({hour:w.sh,minute:w.sm}),e=date.set({hour:w.eh,minute:w.em});if(e>s&&e>now)out.push([s.toUTC(),e.toUTC()]);}}return out;}
async function eligibleAvailabilityRows(guild){const rows=db.prepare('SELECT * FROM staff_availability').all(),out=[];for(const row of rows){const member=await guild.members.fetch(row.staff_id).catch(()=>null);if(!member||!seniorPlus(member))continue;out.push({...row,isLeadership:leadership(member)});}return out;}
async function overlapOptions(guild){const rows=await eligibleAvailabilityRows(guild),slots=[];const addWindow=(start,end,staff,kind)=>{let s=start;while(s.plus({minutes:45})<=end){const ts=Math.floor(s.toSeconds());if(ts>Math.floor(Date.now()/1000)+900)slots.push({ts,staff,kind});s=s.plus({minutes:60});}};
// Owner or Co-Owner can interview/approve by themselves, so their saved availability is immediately selectable.
for(const row of rows.filter(r=>r.isLeadership))for(const w of nextOccurrences(row))addWindow(w[0],w[1],[row.staff_id],'leadership');
// Otherwise, require an overlap between two different Senior Staff interviewers.
const seniors=rows.filter(r=>!r.isLeadership);for(let i=0;i<seniors.length;i++)for(let j=i+1;j<seniors.length;j++)for(const a of nextOccurrences(seniors[i]))for(const b of nextOccurrences(seniors[j])){const start=a[0]>b[0]?a[0]:b[0],end=a[1]<b[1]?a[1]:b[1];if(start<end)addWindow(start,end,[seniors[i].staff_id,seniors[j].staff_id],'two-senior');}
const seen=new Set();return slots.sort((a,b)=>a.ts-b.ts).filter(x=>!seen.has(x.ts)&&(seen.add(x.ts),true)).slice(0,120);}
function clearExpiredReservations(){db.prepare('DELETE FROM interview_slot_reservations WHERE expires_at<=?').run(Math.floor(Date.now()/1000));}
async function availableOptions(id,guild){clearExpiredReservations();const opts=await overlapOptions(guild),reserved=new Set(db.prepare('SELECT ts FROM interview_slot_reservations WHERE app_id<>?').all(id).map(x=>Number(x.ts)));return opts.filter(o=>!reserved.has(o.ts));}
function dayKey(ts){return DateTime.fromSeconds(ts,{zone:'utc'}).setZone('Pacific/Honolulu').toISODate();}
function dayLabel(key){return DateTime.fromISO(key,{zone:'Pacific/Honolulu'}).toFormat('cccc, LLLL d');}
async function dayPicker(id,guild){const opts=await availableOptions(id,guild);if(!opts.length)return null;const days=[];for(const o of opts){const k=dayKey(o.ts);if(!days.includes(k))days.push(k);if(days.length>=7)break;}const menu=new ActionRowBuilder().addComponents(new StringSelectMenuBuilder().setCustomId(`sa:day:${id}`).setPlaceholder('1️⃣ Choose a day').addOptions(days.map(k=>({label:dayLabel(k),value:k,description:`Available interview times on ${dayLabel(k)}`}))));return {menu,days};}
async function timePicker(id,guild,key){const opts=(await availableOptions(id,guild)).filter(o=>dayKey(o.ts)===key).slice(0,25);if(!opts.length)return null;const menu=new ActionRowBuilder().addComponents(new StringSelectMenuBuilder().setCustomId(`sa:picktime:${id}`).setPlaceholder('2️⃣ Choose a time').addOptions(opts.map(o=>({label:DateTime.fromSeconds(o.ts,{zone:'utc'}).setZone('Pacific/Honolulu').toFormat('h:mm a'),description:o.kind==='leadership'?'Interview staff available':'Two interview staff available',value:String(o.ts)}))));return {menu,opts};}
function scheduleEmbed(target,extra=''){return new EmbedBuilder().setTitle(`📅 Choose Your Interview Time — ${rank(target).label}`).setDescription(`Pick a **day**, then choose a **time** that works for you.\n\nDiscord will show the final selected time in **your own timezone**.\n\n✅ Only times with enough interview staff are offered.${extra?`\n\n${extra}`:''}`);}
async function schedulePanel(id,guild,target){const d=await dayPicker(id,guild);if(!d)return null;return {embeds:[scheduleEmbed(target)],components:[d.menu,new ActionRowBuilder().addComponents(new ButtonBuilder().setCustomId(`sa:refreshTimes:${id}`).setLabel('🔄 Refresh').setStyle(ButtonStyle.Secondary))]};}
async function reviewPayload(id){const a=appById(id),ans=JSON.parse(a.answers||'{}'),aps=db.prepare('SELECT * FROM interview_approvals WHERE app_id=?').all(id),seniorCount=aps.filter(x=>x.role_kind==='senior').length,lead=aps.find(x=>x.role_kind==='leadership');const approval=lead?`✅ Confirmed by leadership (<@${lead.staff_id}>)`:`${seniorCount>=2?'✅':'🟡'} Senior Staff approvals: **${seniorCount}/2**`;return {embeds:[new EmbedBuilder().setTitle(`📥 Application #${id} — ${rank(a.target_rank).label}`).setDescription(`<@${a.user_id}>\n**Source:** ${a.source==='direct'?'Direct Interview':'Application'}\n\n**Why:** ${ans.why||'-'}\n\n**Experience:** ${ans.experience||'-'}\n\n**Judgment:** ${ans.judgment||'-'}${a.scheduled_ts?`\n\n**Requested interview:** <t:${a.scheduled_ts}:F> (<t:${a.scheduled_ts}:R>)`:''}\n\n**Interview approval:** ${approval}\n\nThe interview is created only after **Owner/Co-Owner approval OR two different Senior Staff approvals**.`)],components:[new ActionRowBuilder().addComponents(new ButtonBuilder().setCustomId(`sa:review:approve:${id}`).setLabel('Approve Interview').setStyle(ButtonStyle.Success),new ButtonBuilder().setCustomId(`sa:review:reschedule:${id}`).setLabel('Reschedule').setStyle(ButtonStyle.Secondary),new ButtonBuilder().setCustomId(`sa:review:deny:${id}`).setLabel('Deny').setStyle(ButtonStyle.Danger))]};}
async function postReview(id){const a=appById(id),c=await text(REVIEW);if(!c)return;const msg=await c.send(await reviewPayload(id));db.prepare('UPDATE staff_apps SET review_message_id=? WHERE id=?').run(msg.id,id);}
async function makeApplication(g,userId,target,source){const ch=await createPrivateChannel(g,userId,target);const r=db.prepare('INSERT INTO staff_apps(user_id,target_rank,source,status,answers,private_channel_id,created_at) VALUES(?,?,?,?,?,?,?)').run(userId,target,source,'choosing_time','{}',ch.id,Date.now());const id=Number(r.lastInsertRowid),panel=await schedulePanel(id,g,target);if(panel)await ch.send({content:`<@${userId}>`,...panel});else await ch.send({content:`<@${userId}>`,embeds:[new EmbedBuilder().setTitle(`📅 Choose Your Interview Time — ${rank(target).label}`).setDescription('⚠️ **No interview times are available yet.**\n\nA selectable time needs either:\n• an **Owner or Co-Owner** with saved availability, or\n• **two different Senior Staff** whose availability overlaps.')],components:[new ActionRowBuilder().addComponents(new ButtonBuilder().setCustomId(`sa:refreshTimes:${id}`).setLabel('🔄 Refresh Available Times').setStyle(ButtonStyle.Primary))]});return id;}
