function state(a){try{return JSON.parse(a.interview_state||'{}')}catch{return{}}}
function saveState(id,s){db.prepare('UPDATE staff_apps SET interview_state=? WHERE id=?').run(JSON.stringify(s),id)}
function catFor(a,idx){const base=CATEGORIES[idx];return {...base,qs:base.key==='rank'?(SPECIFIC[a.target_rank]||SPECIFIC.general):base.qs};}
function boardEmbed(a,s){if(!s.started)return new EmbedBuilder().setTitle(`🎙️ Interview Board #${a.id}`).setDescription(`**Applicant:** <@${a.user_id}>\n**Target:** ${rank(a.target_rank).label}\n**Status:** 🟡 Waiting\n${a.scheduled_ts?`**Scheduled:** <t:${a.scheduled_ts}:F>\n`:''}\nPress **Start Interview** when the applicant and interviewer are ready.`);const idx=s.category||0,cat=catFor(a,idx),sel=s.selected||[];return new EmbedBuilder().setTitle(`${cat.name} — Category ${idx+1}/8`).setDescription(`**Applicant:** <@${a.user_id}> • **Target:** ${rank(a.target_rank).label}\n\nSelect **exactly 3 questions** for this category. Ask them verbally, then grade the category **0/3–3/3**.\n\n${sel.length?`**Selected questions:**\n${sel.map((n,k)=>`${k+1}. ${cat.qs[n]}`).join('\n')}`:'**No questions selected yet.**'}`);}
function boardComponents(a,s){if(!s.started)return[new ActionRowBuilder().addComponents(new ButtonBuilder().setCustomId(`sa:startInterview:${a.id}`).setLabel('▶️ Start Interview').setStyle(ButtonStyle.Success))];const idx=s.category||0,cat=catFor(a,idx);if(!(s.selected||[]).length)return[new ActionRowBuilder().addComponents(new StringSelectMenuBuilder().setCustomId(`sa:questions:${a.id}:${idx}`).setPlaceholder('Select exactly 3 questions').setMinValues(3).setMaxValues(3).addOptions(cat.qs.map((q,n)=>({label:`Question ${n+1}`,description:q.slice(0,95),value:String(n)}))))];return[new ActionRowBuilder().addComponents([0,1,2,3].map(n=>new ButtonBuilder().setCustomId(`sa:catGrade:${a.id}:${n}`).setLabel(`${n}/3`).setStyle(n===3?ButtonStyle.Success:n===0?ButtonStyle.Danger:ButtonStyle.Primary))),new ActionRowBuilder().addComponents(new ButtonBuilder().setCustomId(`sa:changeQuestions:${a.id}`).setLabel('Change Questions').setStyle(ButtonStyle.Secondary),new ButtonBuilder().setCustomId(`sa:catNotes:${a.id}`).setLabel('Add Notes').setStyle(ButtonStyle.Secondary))];}
async function createInterview(id,g){let a=appById(id);if(!a)return;const member=await g.members.fetch(a.user_id);const overwrites=[{id:g.roles.everyone.id,deny:[PermissionFlagsBits.ViewChannel]},{id:a.user_id,allow:[PermissionFlagsBits.ViewChannel,PermissionFlagsBits.SendMessages,PermissionFlagsBits.ReadMessageHistory]},{id:SENIOR,allow:[PermissionFlagsBits.ViewChannel,PermissionFlagsBits.SendMessages,PermissionFlagsBits.ReadMessageHistory]},{id:HEAD_SENIOR,allow:[PermissionFlagsBits.ViewChannel,PermissionFlagsBits.SendMessages,PermissionFlagsBits.ReadMessageHistory]},{id:COOWNER,allow:[PermissionFlagsBits.ViewChannel,PermissionFlagsBits.SendMessages,PermissionFlagsBits.ReadMessageHistory]},{id:OWNER,allow:[PermissionFlagsBits.ViewChannel,PermissionFlagsBits.SendMessages,PermissionFlagsBits.ReadMessageHistory]}];let tc=a.interview_text_channel_id?await g.channels.fetch(a.interview_text_channel_id).catch(()=>null):null;if(!tc)tc=await g.channels.create({name:`interview-${member.user.username}`.toLowerCase().replace(/[^a-z0-9-]/g,'-').slice(0,90),type:ChannelType.GuildText,parent:APP_CATEGORY,permissionOverwrites:overwrites});let vc=a.voice_channel_id?await g.channels.fetch(a.voice_channel_id).catch(()=>null):null;if(!vc)vc=await g.channels.create({name:`Interview — ${member.displayName}`.slice(0,100),type:ChannelType.GuildVoice,parent:APP_CATEGORY,permissionOverwrites:[{id:g.roles.everyone.id,deny:[PermissionFlagsBits.ViewChannel,PermissionFlagsBits.Connect]},{id:a.user_id,allow:[PermissionFlagsBits.ViewChannel,PermissionFlagsBits.Connect,PermissionFlagsBits.Speak]},{id:SENIOR,allow:[PermissionFlagsBits.ViewChannel,PermissionFlagsBits.Connect,PermissionFlagsBits.Speak]},{id:HEAD_SENIOR,allow:[PermissionFlagsBits.ViewChannel,PermissionFlagsBits.Connect,PermissionFlagsBits.Speak]},{id:COOWNER,allow:[PermissionFlagsBits.ViewChannel,PermissionFlagsBits.Connect,PermissionFlagsBits.Speak]},{id:OWNER,allow:[PermissionFlagsBits.ViewChannel,PermissionFlagsBits.Connect,PermissionFlagsBits.Speak]}]});db.prepare("UPDATE staff_apps SET status='interview_ready',voice_channel_id=?,interview_text_channel_id=? WHERE id=?").run(vc.id,tc.id,id);a=appById(id);const ch=a.private_channel_id?await g.channels.fetch(a.private_channel_id).catch(()=>null):null;if(ch)await ch.send({embeds:[new EmbedBuilder().setTitle('✅ Interview Confirmed').setDescription(`**Position:** ${rank(a.target_rank).label}\n**Interview:** ${a.scheduled_ts?`<t:${a.scheduled_ts}:F> (<t:${a.scheduled_ts}:R>)`:'Time confirmed by staff'}\n**Interview room:** <#${tc.id}>\n**Voice:** <#${vc.id}>`),studyGuideEmbed(a)]});const s={started:false,category:0,grades:{},notes:{}};saveState(id,s);await tc.send({content:`<@${a.user_id}>`,embeds:[boardEmbed(a,s)],components:boardComponents(a,s)});}
